cat << 'EOF' > /tmp/compare_clean.py
import sqlite3
import re

conn = sqlite3.connect('/root/data/eventlogs.db')
conn.row_factory = sqlite3.Row
cursor = conn.cursor()

cursor.execute("SELECT * FROM events")
events = [dict(r) for r in cursor.fetchall()]

# Malicious Process GUIDs
mal_guids = {
    '{860ba2e3-9f13-5f52-2603-000000000400}', # wscript.exe
    '{860ba2e3-9f13-5f52-2703-000000000400}', # powershell.exe
    '{860ba2e3-9f2e-5f52-2a03-000000000400}', # whoami.exe
    '{860ba2e3-9f13-5f52-2803-000000000400}'  # conhost.exe
}

# Malicious PIDs (decimal)
mal_pids_dec = {2440, 2316, 9152, 7700}
mal_pids_hex = {'0x988', '0x90c', '0x23c0', '0x1e14'}

flagged_old = set()
flagged_new = set()

for e in events:
    eid = e['event_id']
    code = e['event_code']
    msg = e['message'] or ''
    guid = e['process_guid']
    pguid = e['parent_process_guid']

    # Logic 1 (Old)
    if guid in mal_guids or pguid in mal_guids:
        flagged_old.add(eid)
    else:
        for g in mal_guids:
            if g in msg:
                flagged_old.add(eid)
                break
        if eid not in flagged_old:
            if code in (800, 4103, 4104, 400, 600) and e['host'] == 'WS-05.corp.example':
                flagged_old.add(eid)
            elif code in (5156, 5158) and e['host'] == 'WS-05.corp.example' and ('powershell.exe' in msg.lower() or 'wscript.exe' in msg.lower()):
                flagged_old.add(eid)
            else:
                for p in mal_pids_hex:
                    if p in msg.lower():
                        flagged_old.add(eid)
                        break
                if eid not in flagged_old:
                    for p in mal_pids_dec:
                        if f"ProcessId: {p}" in msg or f"Process ID: {p}" in msg or f"Process ID:\t\t{hex(p)}" in msg:
                            flagged_old.add(eid)
                            break

    # Logic 2 (New)
    if guid in mal_guids:
        flagged_new.add(eid)
    elif code in (800, 4103, 4104, 400, 600) and e['host'] == 'WS-05.corp.example':
        flagged_new.add(eid)
    else:
        # Check if the process executing is malicious
        pid_matches = re.findall(r'Process ID:\s*(0x[0-9A-Fa-f]+|\d+)', msg)
        new_pid_matches = re.findall(r'New Process ID:\s*(0x[0-9A-Fa-f]+|\d+)', msg)
        creator_pid_matches = re.findall(r'Creator Process ID:\s*(0x[0-9A-Fa-f]+|\d+)', msg)
        pids_found = set()
        for val in pid_matches + new_pid_matches + creator_pid_matches:
            val = val.strip()
            if val.startswith('0x'):
                pids_found.add(int(val, 16))
            elif val.isdigit():
                pids_found.add(int(val))
        for pid in pids_found:
            if pid in mal_pids_dec:
                flagged_new.add(eid)
                break

diff = flagged_old - flagged_new
print(f"Flagged Old: {len(flagged_old)}, Flagged New: {len(flagged_new)}, Diff: {len(diff)}")
for eid in sorted(list(diff)):
    cursor.execute("SELECT * FROM events WHERE event_id = ?", (eid,))
    e = dict(cursor.fetchone())
    print(f"{eid}: Code={e['event_code']}, Src={e['image']}, Target={e['target_image']}, MsgSummary={e['message'][:150].strip().replace('\n', ' ')}")
EOF
